from migrations.canonical.schema_contract import CANONICAL_REVISION, CONSTRAINTS, INDEXES, TABLES


def test_canonical_schema_contract_is_explicit_and_covers_final_hardening():
    assert CANONICAL_REVISION == "0027_report_config_trash"
    assert {"devices", "device_availability", "operational_events", "alarms", "alarm_history", "maintenance_windows", "notification_policies", "notification_policy_steps", "notification_deliveries", "device_ips", "recycle_bin_batches", "audit_logs", "restore_points", "system_settings", "user_resource_scopes", "telemetry_profiles", "telemetry_metrics", "data_retention_policies", "report_jobs", "report_deliveries"} <= TABLES
    assert {"ck_device_availability_status", "ck_device_availability_profile", "ck_alarms_state", "ck_alarm_history_action", "ck_maintenance_windows_target_type", "ck_notification_policies_minimum_severity", "ck_notification_deliveries_status", "ck_device_ips_primary_requires_management", "ck_recycle_bin_batches_status", "ck_restore_points_status", "ck_device_groups_system_dynamic", "ck_user_resource_scopes_target", "ck_cities_service_vlan_id", "ck_sectors_customer_vlan_range", "ck_customer_services_customer_vlan_id", "ck_import_jobs_status", "ck_telemetry_metrics_kind", "ck_data_lifecycle_runs_status", "ck_report_jobs_status", "ck_report_definitions_trash_state", "ck_report_schedules_trash_state", "ck_report_deliveries_status"} <= CONSTRAINTS
    assert {"uq_device_availability_device", "ix_device_availability_due", "uq_alarms_correlation_key", "ix_alarm_history_alarm_occurred_at", "ix_maintenance_windows_active_time", "uq_notification_deliveries_idempotency", "ix_notification_deliveries_due", "uq_active_device_ips_primary", "ix_audit_logs_occurred_at", "ix_recycle_bin_batches_due_purge", "uq_device_groups_system_key", "uq_user_resource_scopes_global_user", "ix_user_resource_scopes_user_type", "uq_cities_service_vlan_id", "ix_customer_services_customer_vlan", "ix_telemetry_metrics_device_metric_time", "ix_report_jobs_status_created", "ix_report_definitions_owner_deleted", "ix_report_schedules_purge_after", "ix_report_deliveries_due"} <= INDEXES

